import{_ as e,r as a,o,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const h=JSON.parse('{"title":"collect() - October CMS - 3.x","titleTemplate":false,"description":"Twig 函数","frontmatter":{"subtitle":"Twig 函数"},"headers":[{"level":2,"title":"shuffle","slug":"shuffle","link":"#shuffle","children":[]},{"level":2,"title":"sortBy","slug":"sortby","link":"#sortby","children":[{"level":4,"title":"参见","slug":"参见","link":"#参见","children":[]}]}],"relativePath":"3.x/zh-cn/markup/function/collect.md","filePath":"3.x/zh-cn/markup/function/collect.md"}'),u={name:"3.x/zh-cn/markup/function/collect.md"};function k(r,n,g,d,m,w){const t=a("pre-heading"),p=a("post-heading");return o(),c("div",null,[s(t),n[0]||(n[0]=l("h1",null,"collect()",-1)),s(p),n[1]||(n[1]=i(`<p><code>collect()</code> 函数为在 Twig 中构建数组提供了更友好的接口。Twig 作为视图层有意保持简约，构建数组需要持续的合并过程。</p><p>以下示例使用原生 Twig <code>|merge</code> 过滤器来构建数组：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> array <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> item <span class="token operator">in</span> items <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> array <span class="token operator">=</span> array<span class="token operator">|</span>merge<span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">{</span> title<span class="token punctuation">:</span> item<span class="token punctuation">.</span>title<span class="token punctuation">,</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>使用 <code>collect()</code> 函数返回<a href="./../../extend/services/collection.html">一个集合对象</a>，允许您使用 push 方法添加元素。上述示例可以使用 <code>push</code> 方法实现。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> array <span class="token operator">=</span> collect<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> item <span class="token operator">in</span> items <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> array<span class="token punctuation">.</span>push<span class="token punctuation">(</span><span class="token punctuation">{</span> title<span class="token punctuation">:</span> item<span class="token punctuation">.</span>title<span class="token punctuation">,</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>将数组作为第一个参数传递可以用预填充的项目初始化集合。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> array <span class="token operator">=</span> collect<span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token punctuation">{</span> title<span class="token punctuation">:</span> item<span class="token punctuation">.</span>title<span class="token punctuation">,</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">{</span> title<span class="token punctuation">:</span> item<span class="token punctuation">.</span>title<span class="token punctuation">,</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">}</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="shuffle"><a href="#shuffle" class="header-anchor">#</a> shuffle</h2><p><code>shuffle()</code> 方法用于随机打乱集合。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> collect<span class="token punctuation">(</span>songs<span class="token punctuation">)</span><span class="token punctuation">.</span>shuffle<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>在 foreach 循环中使用。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> fruit <span class="token operator">in</span> collect<span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string"><span class="token punctuation">&#39;</span>apple<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>banana<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>orange<span class="token punctuation">&#39;</span></span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">.</span>shuffle<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> fruit <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="sortby"><a href="#sortby" class="header-anchor">#</a> sortBy</h2><p><code>sortBy()</code> 和 <code>sortByDesc</code> 方法可以按给定字段（键）对集合进行排序。</p><div class="language-twig extra-class"><pre class="language-twig"><code>collect(data).sortBy(&#39;age&#39;)
</code></pre></div><p>例如：</p><div class="language-twig extra-class"><pre class="language-twig"><code>// Output: John David
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> data <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">{</span><span class="token string"><span class="token punctuation">&#39;</span>name<span class="token punctuation">&#39;</span></span><span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>David<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>age<span class="token punctuation">&#39;</span></span><span class="token punctuation">:</span> <span class="token number">31</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token punctuation">{</span><span class="token string"><span class="token punctuation">&#39;</span>name<span class="token punctuation">&#39;</span></span><span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>John<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>age<span class="token punctuation">&#39;</span></span><span class="token punctuation">:</span> <span class="token number">28</span><span class="token punctuation">}</span><span class="token punctuation">]</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> item <span class="token operator">in</span> collect<span class="token punctuation">(</span>data<span class="token punctuation">)</span><span class="token punctuation">.</span>sortBy<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>age<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> item<span class="token punctuation">.</span>name <span class="token delimiter punctuation">}}</span></span><span class="token entity named-entity" title=" ">&amp;nbsp;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h4 id="参见"><a href="#参见" class="header-anchor">#</a> 参见</h4><div class="custom-block also"><ul><li><a href="./../../cms/resources/building-apis.html">构建 API 资源</a></li></ul></div>`,19))])}const y=e(u,[["render",k]]);export{h as __pageData,y as default};
